-- Acervo: tese de Marylyn Ellen White sobre o Conselho de Yahweh (19/11/2026).
-- Publicada por decisão de Gabriel enquanto o pedido de autorização (via Mohr Siebeck) aguarda resposta.
INSERT INTO artigos (slug,status,tipo,titulo,titulo_original,autor,autor_citacao,afiliacao,tradutor,periodico,volume,numero,ano,mes,paginas_original,editora_original,url_original,area,tema,tema_en,resumo,resumo_en,resumo_editorial,palavras_chave,direitos,pdf_url,pdf_paginas,capa_url,publicado_em) VALUES
('white-conselho-de-yahweh','publicado','traducao','O Conselho de Yahweh: sua estrutura e membros','The Council of Yahweh: Its Structure and Membership','Marylyn Ellen White','WHITE, Marylyn Ellen','University of St. Michael''s College, Toronto','Gabriel Cantarino','Tese de doutorado (Ph.D. em Teologia), University of St. Michael''s College',NULL,NULL,'2012',NULL,NULL,'University of St. Michael''s College (Toronto); versão revista publicada como Yahweh''s Council: Its Structure and Membership (Mohr Siebeck, FAT II 65, 2014)',NULL,'Antigo Testamento','Concílio divino','Divine council','Nesta tese a autora estabelece cinco critérios para identificar um texto do Conselho de Yahweh: há múltiplos deuses presentes; o cenário é o céu; há julgamento; há alguma forma de deliberação; e Yahweh é quem preside o conselho. Por esses critérios, os textos do Conselho de Yahweh são Isaías 6, 1 Reis 22, Jó 1–2, Zacarias 3 e Daniel 7. Em seguida, com os critérios de ser nomeado, ser testemunha e estar envolvido, além do contexto literário, examina esses textos para saber quais personagens são membros do conselho. Estabelecido o elenco, propõe uma estrutura em três níveis: o primeiro pertence ao deus principal, Yahweh; o segundo reúne os conselheiros, em duas divisões; o terceiro reúne os agentes, divididos entre comissionados e oficiais. Por fim, avalia a possibilidade de evolução conceitual, sobretudo em relação ao monoteísmo e à participação de seres humanos no Conselho de Yahweh.','In this dissertation the author sets out five criteria for identifying a Council of Yahweh text: multiple gods are present; the setting is heaven; there is judgment; there is some form of deliberation; and Yahweh leads the council. By these criteria the Council of Yahweh texts are Isaiah 6, 1 Kings 22, Job 1–2, Zechariah 3 and Daniel 7. Using the criteria of being named, witnessing and being involved, together with literary context, she then examines these texts to determine which characters are members of the council. Having established a cast of members, she proposes a three-tiered structure: the first tier belongs to the head god, Yahweh; the second holds the counsellors, in two divisions; the third holds the agents, divided into commissioned agents and officials. Finally, she assesses the potential for conceptual evolution, especially with respect to monotheism and the participation of human beings in the Council of Yahweh.',0,'["concílio divino", "Conselho de Yahweh", "Isaías 6", "1 Reis 22", "Jó 1–2", "Zacarias 3", "Daniel 7", "monoteísmo", "ha-satan", "profetas"]','© Marylyn Ellen White, 2012 (tese de doutorado, University of St. Michael''s College). Uma versão revista foi publicada como Yahweh''s Council: Its Structure and Membership (Tübingen: Mohr Siebeck, 2014). Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, publicada para fins de estudo, sem fins lucrativos. O pedido de autorização à autora foi enviado; o texto será retirado a pedido da detentora dos direitos.','/artigos/white-2012-conselho-de-yahweh.pdf',130,'/artigos/white-2012-conselho-de-yahweh-capa.jpg','2026-11-19 18:15:00');
